export const TOKENS = {
  rosa: 'tok-rosa',   // practitioner, Juniper Hollow
  malik: 'tok-malik', // practitioner, Juniper Hollow
  dana: 'tok-dana',   // admin, Juniper Hollow
  ava: 'tok-ava',     // patient of Rosa
  theo: 'tok-theo',   // patient of Rosa
  priya: 'tok-priya', // patient of Malik
  hal: 'tok-hal',     // practitioner, Fernside (other practice)
  june: 'tok-june',   // patient, Fernside
} as const;

type AnyHandler = (req: Request, ctx: any) => Promise<Response>;

export async function call(
  handler: AnyHandler,
  opts: { method?: string; path?: string; token?: string; body?: unknown; params?: Record<string, string> } = {},
): Promise<{ status: number; json: any; text: string }> {
  const headers: Record<string, string> = {};
  if (opts.token) headers.authorization = `Bearer ${opts.token}`;
  if (opts.body !== undefined) headers['content-type'] = 'application/json';
  const req = new Request(`http://localhost${opts.path ?? '/'}`, {
    method: opts.method ?? 'GET',
    headers,
    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
  });
  const res = await handler(req, { params: Promise.resolve(opts.params ?? {}) });
  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = null;
  }
  return { status: res.status, json, text };
}
import { execute } from './db';
import type { CurrentUser } from './auth';

/** Records who did what to which record. Store ids only, never content. */
export async function audit(user: CurrentUser, action: string, targetType: string, targetId: string): Promise<void> {
  await execute(
    'INSERT INTO audit_log (user_id, action, target_type, target_id) VALUES (?, ?, ?, ?)',
    [user.id, action, targetType, targetId],
  );
}
import { NextResponse } from 'next/server';
import { ZodError } from 'zod';

export class HttpError extends Error {
  constructor(public readonly status: number, public readonly publicMessage: string) {
    super(publicMessage);
  }
}

export function json(data: unknown, status = 200): NextResponse {
  return NextResponse.json(data, { status });
}

type Handler<C> = (req: Request, ctx: C) => Promise<Response>;

/**
 * Wraps a route handler: known HttpErrors become JSON `{ error }` responses,
 * validation errors become 400, anything else becomes a 500.
 */
export function route<C = unknown>(handler: Handler<C>): Handler<C> {
  return async (req, ctx) => {
    try {
      return await handler(req, ctx);
    } catch (err) {
      if (err instanceof HttpError) return json({ error: err.publicMessage }, err.status);
      if (err instanceof ZodError) return json({ error: 'invalid_request' }, 400);
      return new Response(null, { status: 500 });
    }
  };
}

export async function readJson(req: Request): Promise<unknown> {
  try {
    return await req.json();
  } catch {
    throw new HttpError(400, 'invalid_json');
  }
}
