import { audit } from '@/lib/audit';
import { requireUser } from '@/lib/auth';
import { json, route, HttpError } from '@/lib/http';
import * as appointments from '@/repos/appointments';
import * as messages from '@/repos/messages';
import * as notes from '@/repos/notes';
import { getPatient } from '@/repos/patients';

/** The signed-in patient's own general record. Psychotherapy notes are excluded. */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'patient' || !user.patientId) throw new HttpError(403, 'forbidden');
  const p = await getPatient(user.patientId);
  if (!p || p.org_id !== user.orgId) throw new HttpError(404, 'not_found');

  const [appts, msgs, clinical] = await Promise.all([
    appointments.listForExport(p.id),
    messages.listForExport(user.id),
    notes.listClinicalForExport(p.id),
  ]);

  await audit(user, 'export.read', 'patient', p.id);

  const res = json({
    patient: {
      id: p.id,
      firstName: p.first_name,
      lastName: p.last_name,
      dateOfBirth: p.date_of_birth,
      email: p.email,
      phone: p.phone,
      mrn: p.mrn,
    },
    appointments: appts.map((a) => ({
      id: a.id,
      startsAt: a.starts_at,
      endsAt: a.ends_at,
      status: a.status,
      visitReason: a.visit_reason,
    })),
    messages: msgs.map((m) => ({
      id: m.id,
      subject: m.subject,
      body: m.body,
      sentAt: m.created_at,
      direction: m.sender_user_id === user.id ? 'sent' : 'received',
    })),
    clinicalNotes: clinical.map((n) => ({ id: n.id, createdAt: n.created_at, body: n.body })),
  });
  res.headers.set('cache-control', 'no-store');
  return res;
});
EOF
cat > tests/export.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { GET } from '@/app/api/me/export/route';
import { call, TOKENS } from './helpers';

describe('GET /api/me/export', () => {
  it('exports the patient\'s own general record only', async () => {
    const res = await call(GET, { token: TOKENS.ava });
    expect(res.status).toBe(200);
    expect(res.json.patient.id).toBe('pt_ava');
    expect(res.json.patient.mrn).toBeTruthy();
    expect(res.json.appointments.map((a: any) => a.id).sort()).toEqual(['apt_001', 'apt_004']);
    expect(res.json.clinicalNotes.map((n: any) => n.id).sort()).toEqual(['cn_001', 'cn_002']);
    const dirs = Object.fromEntries(res.json.messages.map((m: any) => [m.id, m.direction]));
    expect(dirs).toEqual({ msg_001: 'received', msg_002: 'sent' });
    expect(res.text).not.toContain('transference');
    expect(res.text).not.toContain('pn_001');
    expect(res.text).not.toContain('Bring sleep diary');
    expect(res.text).not.toContain('Theo');
    expect(res.text).not.toContain('abstinent');
  });

  it('does not leak another patient\'s data', async () => {
    const res = await call(GET, { token: TOKENS.june });
    expect(res.status).toBe(200);
    expect(res.json.patient.id).toBe('pt_june');
    expect(res.json.clinicalNotes).toEqual([]);
    expect(res.text).not.toContain('Ava');
  });

  it.each(['rosa', 'dana', 'hal'] as const)('refuses %s with 403', async (who) => {
    expect((await call(GET, { token: TOKENS[who] })).status).toBe(403);
  });

  it('requires authentication', async () => {
    expect((await call(GET)).status).toBe(401);
  });
});
